/**
 * Ravae Record - Ingestion & Super Admin Review System
 * Google Apps Script Integration for Google Drive
 * 
 * Auto-generated by The Backstage Operations Hub
 * Connected to Antigravity Shared Data Sync Engine
 */

// CONFIGURATION: Google Drive Root Folder ID for "RAVAE STUDIO (FILE SYSTEM)"
var ROOT_FOLDER_ID = "RAVAE-STUDIO-ROOT";

var COMPANY_NAME = "Ravae Record";
var PRODUCER_MAPPING = {
  "Yung Ravae": "VaeDaVisonary",
  "yung ravae": "VaeDaVisonary",
  "Old Ravae": "VaeDaVisonary",
  "OLD RAVAE": "VaeDaVisonary",
  "Ravae Records": "Ravae Record"
};

/**
 * Applies rebranding rules to text inputs and file names.
 */
function applyRavaeRebrandOverrides(textInput) {
  if (!textInput) return textInput;
  
  // Replace Ravae Records -> Ravae Record
  textInput = textInput.replace(/Ravae Records/g, COMPANY_NAME);
  
  // Map producer aliases -> VaeDaVisonary
  for (var oldAlias in PRODUCER_MAPPING) {
    var regex = new RegExp(oldAlias, "gi");
    textInput = textInput.replace(regex, PRODUCER_MAPPING[oldAlias]);
  }
  return textInput;
}

/**
 * Finds or creates a subfolder by path inside a parent folder.
 */
function getOrCreateFolderByPath(parentFolder, pathSegments) {
  var currentFolder = parentFolder;
  for (var i = 0; i < pathSegments.length; i++) {
    var segment = pathSegments[i];
    var folders = currentFolder.getFoldersByName(segment);
    if (folders.hasNext()) {
      currentFolder = folders.next();
    } else {
      currentFolder = currentFolder.createFolder(segment);
    }
  }
  return currentFolder;
}

/**
 * UPLOAD NEW WORKS (Producer / Creator Ingestion Endpoint)
 * Uploads file directly to '00_Uploads_Pending_Review' staging folder.
 */
function uploadNewWork(creatorName, role, fileName, rightsTier, fileBlob) {
  var rootFolder = DriveApp.getFolderById(ROOT_FOLDER_ID);
  
  // Apply rebranding overrides
  var cleanCreator = applyRavaeRebrandOverrides(creatorName);
  var cleanFileName = applyRavaeRebrandOverrides(fileName);
  
  // Determine subfolder based on role
  var roleFolder = (role.toLowerCase() === "producer" || role.toLowerCase().includes("beat")) ? "Producers" : "Content_Creators";
  var stagingFolder = getOrCreateFolderByPath(rootFolder, ["00_Uploads_Pending_Review", roleFolder]);
  
  // Create file in staging folder
  fileBlob.setName(cleanFileName);
  var stagedFile = stagingFolder.createFile(fileBlob);
  
  // Apply custom metadata properties
  stagedFile.setDescription(
    "STATUS: PENDING_SUPER_ADMIN_REVIEW\n" +
    "Creator: " + cleanCreator + "\n" +
    "Role: " + role + "\n" +
    "Rights Tier: " + rightsTier
  );
  
  return {
    status: "SUCCESS",
    fileId: stagedFile.getId(),
    fileName: cleanFileName,
    creator: cleanCreator,
    url: stagedFile.getUrl()
  };
}

/**
 * SUPER ADMIN: Get Pending Review Queue
 * Fetches all files currently awaiting approval in staging.
 */
function getSuperAdminReviewQueue() {
  var rootFolder = DriveApp.getFolderById(ROOT_FOLDER_ID);
  var stagingFolder = getOrCreateFolderByPath(rootFolder, ["00_Uploads_Pending_Review"]);
  
  var pendingQueue = [];
  var subFolders = stagingFolder.getFolders();
  
  while (subFolders.hasNext()) {
    var subFolder = subFolders.next();
    var files = subFolder.getFiles();
    while (files.hasNext()) {
      var file = files.next();
      pendingQueue.push({
        fileId: file.getId(),
        fileName: file.getName(),
        folderName: subFolder.getName(),
        description: file.getDescription(),
        url: file.getUrl(),
        dateCreated: file.getDateCreated()
      });
    }
  }
  
  return pendingQueue;
}

/**
 * SUPER ADMIN: Approve & Move Beat
 * Moves approved beat from staging to target Google Drive catalog path.
 */
function approveAndCatalogBeat(fileId, targetPathSegments) {
  var file = DriveApp.getFileById(fileId);
  var rootFolder = DriveApp.getFolderById(ROOT_FOLDER_ID);
  
  // Ensure target folder exists
  var targetFolder = getOrCreateFolderByPath(rootFolder, targetPathSegments);
  
  // Move file to final target folder
  file.moveTo(targetFolder);
  
  // Update description status
  file.setDescription(file.getDescription().replace("PENDING_SUPER_ADMIN_REVIEW", "APPROVED"));
  
  return {
    status: "APPROVED",
    fileName: file.getName(),
    newUrl: file.getUrl()
  };
}
